        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine().trim();
        int n = s.length();
        Set<String> distinct = new HashSet<>();

        for (int i = 0; i < n; i++) {
            // Move last character to front i times
            String current = s;
            for (int j = 0; j < i; j++) {
                current = current.substring(current.length() - 1) + current.substring(0, current.length() - 1);
            }
            distinct.add(current);
        }

        System.out.println(distinct.size());
    }
