import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNext()) {
            String s = scanner.next();
            int n = s.length();
            Set<String> distinctWords = new HashSet<>();
            for (int i = 0; i < n; i++) {
                // Move the last character to the beginning
                // Equivalent to rotating the string
                String rotated = s.substring(n - 1) + s.substring(0, n - 1);
                distinctWords.add(rotated);
                s = rotated;
            }
            // The initial string is also counted. 
            // Note: The loop above generates n rotations. 
            // If we start with s0, after 1 shift we get s1, ..., after n-1 shifts we get s_{n-1}.
            // The set will contain all distinct strings among s0, s1, ..., s_{n-1}.
            // Wait, the loop above starts by modifying s. 
            // Let's trace:
            // Initial s = "abcd"
            // i=0: rotated = "d" + "abc" = "dabc". Add "dabc". s becomes "dabc".
            // i=1: rotated = "c" + "dab" = "cdab". Add "cdab". s becomes "cdab".
            // i=2: rotated = "b" + "cda" = "bcda". Add "bcda". s becomes "bcda".
            // i=3: rotated = "a" + "bcd" = "abcd". Add "abcd". s becomes "abcd".
            // So the set contains all n rotations including the original.
            System.out.println(distinctWords.size());
        }
        scanner.close();
    }
}

