import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNext()) {
            String s = scanner.next();
            int n = s.length();
            Set<String> distinctWords = new HashSet<>();

            for (int i = 0; i < n; i++) {
                // Generate the cyclic shift by moving the last character to the beginning
                // This is equivalent to rotating the string to the right by 1
                // Or simply, we can generate all rotations by taking substrings
                // Rotation i: s.substring(n - i) + s.substring(0, n - i)
                // But it's easier to just simulate the shift or use string manipulation
                // Let's use the property that cyclic shifts are rotations.
                // Rotation 0: s
                // Rotation 1: last char + rest
                // We can generate all n rotations.

                // A simpler way to get the i-th rotation (where i is number of shifts applied):
                // After 1 shift: s[n-1] + s[0..n-2]
                // After 2 shifts: s[n-2] + s[n-1] + s[0..n-3]
                // Generally, after k shifts, the string is s[n-k..n-1] + s[0..n-k-1]

                // Let's just generate all n possible rotations.
                // Rotation i corresponds to moving the last i characters to the front?
                // No, the problem says "moves the last character of the word to the beginning".
                // So:
                // Start: s
                // Shift 1: s[n-1] + s[0..n-2]
                // Shift 2: s[n-2] + s[n-1] + s[0..n-3]

                // We can just construct the string for each shift count from 0 to n-1.
                // Shift 0: s
                // Shift k: s.substring(n-k) + s.substring(0, n-k)

                String rotated = s.substring(n - i) + s.substring(0, n - i);
                distinctWords.add(rotated);
            }

            System.out.println(distinctWords.size());
        }
        scanner.close();
    }
}

